"""Build a standalone, shareable HTML report from saved numerical results."""
import base64
import html
import json
from pathlib import Path
import pandas as pd
from audit import ROOT


def pct(x,digits=1):
    return '—' if pd.isna(x) else f'{100*x:,.{digits}f}%'


def table(rows,columns):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'


def image(name,caption):
    data=base64.b64encode((ROOT/'reports/figures'/name).read_bytes()).decode()
    return f'<figure><img src="data:image/png;base64,{data}" alt="{html.escape(caption)}"><figcaption>{html.escape(caption)}</figcaption></figure>'


def run():
    cats=pd.read_csv(ROOT/'results/categories.csv').set_index('category')
    from analyze import heatmap
    heatmap(cats.reset_index())
    candidates=pd.read_csv(ROOT/'results/candidate_details.csv').set_index('category')
