    summary=json.loads((ROOT/'results/analysis_summary.json').read_text())
    mapping=json.loads((ROOT/'results/kalshi_price_reconstruction.json').read_text())
    robust=json.loads((ROOT/'results/robustness_summary.json').read_text())
    kelly=json.loads((ROOT/'results/kelly_summary.json').read_text())
    core=candidates.loc['C4-5 / all prices']
    rows=[]
