    shortlist=table(rows,['Confidence','Kalshi YES ask for original pick','Wins / bets','Net ROI','Approx. 95% card-cluster interval','Model P(edge > 0)*','Interpretation'])
    temporal=pd.read_csv(ROOT/'results/candidate_temporal.csv')
